        a = stride === 4 ? data[i+3] : separateAlpha?.[i/3] ?? max;
      if (r > max || g > max || b > max || a > max) throw new RangeError('Reference sample exceeds its maximum');
      if (transparency.add(a,max)) hist.add(pack(byte(r),byte(g),byte(b)));
