    if (Math.hypot(x, z) <= 1e-6 * Math.hypot(...view)) return color;
    const lateral = profile.colors[x < 0 ? 0 : 1] ?? color;
    const longitudinal = profile.colors[z >= 0 ? 2 : 3] ?? color;
    const a = Math.abs(x), b = Math.abs(z);
    let weight = Number(b > a);
