          ca = Math.cos(a),
          sa = Math.sin(a),
          p = [c[0] + sx[0] * ca * R, c[1] + spring + sa * R, c[2] + sx[2] * ca * R],
          rad = [sx[0] * ca, sa, sx[2] * ca],
          tan = [-sx[0] * sa, ca, -sx[2] * sa];
