  const xyz=a=>Array.isArray(a)&&a.length===3&&Array.from(a).every(Number.isFinite);
  const record=a=>a&&Object.getPrototypeOf(a)===Object.prototype;
  const name=a=>typeof a==='string'&&a.trim().length&&a.length<=96;
